import { classesDe, umDe } from '../nucleo/classes';

export type UcamSiteContainerWidth = 'miolo' | 'faixa' | 'prosa';
export type UcamSiteSecaoTone = 'default' | 'sutil';

const LARGURAS = ['miolo', 'faixa', 'prosa'] as const;
const TONS = ['default', 'sutil'] as const;

/*
 * A moldura da página. Contrato: sites/spec/components/page-shell.json.
 *
 * Cinco diretivas, uma por elemento do contrato, e nenhuma com template: a
 * página é do consumidor, e a moldura só diz qual elemento é o quê. O href
 * do link de salto e o id do <main> são nativos.
 */

/** A raiz da página: `<div ucamSitePage>` ou o `<body>`. */
@Directive({ selector: '[ucamSitePage]', host: { class: 'ucam-site-page' } })
export class UcamSitePage {}

/**
 * O link de salto, o primeiro foco da página: `<a ucamSiteSkip href="#conteudo">`.
 *
 * A diretiva trata o clique: leva o foco ao alvo e não deixa o navegador
 * seguir o href. Um href só de âncora resolve contra o <base href> do
 * documento, e todo app Angular tem <base href="/">: numa página interna,
 * "ir para o conteúdo" recarregava a home (revisão de 13/10/2026). Sem
 * script o href continua lá, e funciona onde não há <base>.
 */
@Directive({ selector: 'a[ucamSiteSkip]', host: { class: 'ucam-site-skip', '(click)': 'saltar($event)' } })
export class UcamSiteSkip {
  private readonly el = inject<ElementRef<HTMLAnchorElement>>(ElementRef);

  protected saltar(evento: Event): void {
    const link = this.el.nativeElement;
    const id = (link.getAttribute('href') ?? '').split('#')[1];
    const alvo = id ? link.ownerDocument.getElementById(decodeURIComponent(id)) : null;
    if (!alvo) return;
    evento.preventDefault();
    // <main> não recebe foco sozinho; -1 o deixa focável sem entrar na ordem do Tab.
    if (!alvo.hasAttribute('tabindex')) alvo.setAttribute('tabindex', '-1');
    alvo.focus();
    alvo.scrollIntoView?.();
  }
}

/** O conteúdo principal: `<main ucamSitePageMain id="conteudo">`. */
@Directive({ selector: 'main[ucamSitePageMain]', host: { class: 'ucam-site-page__main' } })
export class UcamSitePageMain {}

/** Uma seção da página, com o respiro vertical: `<section ucamSiteSecao tone="sutil">`. */
@Directive({ selector: '[ucamSiteSecao]', host: { '[class]': 'classes()' } })
export class UcamSiteSecao {
  readonly tone = input<UcamSiteSecaoTone, UcamSiteSecaoTone | null | undefined>('default', { transform: umDe(TONS, 'default') });

  protected readonly classes = computed(() => classesDe('ucam-site-secao', this.tone() === 'sutil' && 'sutil'));
}

/** O contêiner, que tem a largura máxima e a margem lateral: `<div ucamSiteContainer width="prosa">`. */
@Directive({ selector: '[ucamSiteContainer]', host: { '[class]': 'classes()' } })
export class UcamSiteContainer {
  readonly width = input<UcamSiteContainerWidth, UcamSiteContainerWidth | null | undefined>('miolo', { transform: umDe(LARGURAS, 'miolo') });

  protected readonly classes = computed(() => classesDe('ucam-site-container', this.width() !== 'miolo' && this.width()));
}
","import { ChangeDetectionStrategy, Component, Directive, ViewEncapsulation, booleanAttribute, computed, inject, input, linkedSignal, output } from '@angular/core';
import { UcamSiteIcon } from '../icon/icon';

/**
 * A raiz do acordeão: `<div ucamSiteAccordion name="faq">`.
 * Contrato: sites/spec/components/accordion.json.
 *
 * O `name` é o do grupo: vira o atributo name de cada <details> de dentro, e
 * é o navegador que fecha os outros quando um abre. Sem name, cada item abre
 * e fecha sozinho.
 */
@Directive({
  selector: '[ucamSiteAccordion]',
  host: { class: 'ucam-site-accordion' },
})
export class UcamSiteAccordion {
  readonly name = input<string | null | undefined>(null);

  /** O nome aparado, ou null: grupo de nome vazio não é grupo. */
  readonly grupo = computed(() => this.name()?.trim() || null);
}

/**
 * Um item: `<details ucamSiteAccordionItem heading="Pergunta">resposta</details>`.
 *
 * O estado mora no <details>, que abre e fecha sem script. A peça só o
 * espelha: `open` diz como nasce (e o muda depois), e `openChange` avisa
 * quando o usuário — ou o grupo, ao fechar os vizinhos — o alterna. Por isso
 * `[(open)]` funciona.
 */
@Component({
  selector: 'details[ucamSiteAccordionItem]',
  imports: [UcamSiteIcon],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    class: 'ucam-site-accordion__item',
    '[attr.name]': 'acordeao?.grupo() ?? null',
    '[open]': 'aberto()',
    '(toggle)': 'aoAlternar($event)',
  },
  template: `<summary class="ucam-site-accordion__trigger">{{ heading() }} @if (nota(); as m) {<span class="ucam-site-accordion__meta">{{ m }}</span>}<span class="ucam-site-accordion__icon" aria-hidden="true"><svg ucamSiteIcon="chevronDown"></svg></span></summary><div class="ucam-site-accordion__panel"><ng-content /></div>`,
})
export class UcamSiteAccordionItem {
  readonly heading = input.required<string>();
  /** Texto curto à direita do título: uma contagem, uma data. Faz parte do nome do gatilho. */
  readonly meta = input<string | number | null | undefined>(null);
  readonly open = input(false, { transform: booleanAttribute });
  readonly openChange = output<boolean>();

  protected readonly nota = computed(() => {
    const m = this.meta();
    return typeof m === 'number' || typeof m === 'string' ? String(m).trim() || null : null;
  });
  protected readonly acordeao = inject(UcamSiteAccordion, { optional: true });
  /** O estado atual: nasce de `open` e acompanha o <details>. */
  protected readonly aberto = linkedSignal(() => this.open());

  protected aoAlternar(evento: Event): void {
    const real = (evento.target as HTMLDetailsElement).open;
    if (real === this.aberto()) return;
    this.aberto.set(real);
    this.openChange.emit(real);
  }
}
","import { APP_ID, Injectable, inject } from '@angular/core';

/**
 * Ids para ligar rótulo, campo e mensagens quando o consumidor não dá um.
 *
 * É um serviço da aplicação, não um contador de módulo: no servidor um
 * contador de módulo atravessaria as requisições, e a segunda página renderizada
 * já nasceria com ids diferentes dos que o cliente gera ao hidratar. Por
 * aplicação, servidor e cliente criam as peças na mesma ordem e chegam aos
 * mesmos ids.
 *
 * Com mais de uma aplicação Angular na página, cada uma tem o seu APP_ID, e
 * ele entra no id: as duas começam a contar do 1. Com @defer ou hidratação
 * incremental a ordem de criação pode diferir entre servidor e cliente; aí
 * vale passar `fieldId`.
 */
@Injectable({ providedIn: 'root' })
export class UcamSiteIds {
  private n = 0;
  private readonly app = inject(APP_ID);

  proximo(prefixo: string): string {
    // 'ng' é o APP_ID de fábrica: fora dele, a aplicação se identifica no id.
    return `${prefixo}-${this.app === 'ng' ? '' : this.app + '-'}${++this.n}`;
  }
}
